// Story and handbook are presentation state; opening either never changes a save.
const esc=t=>String(t).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const PROLOGUE=[
 {label:'I / THE QUIET YEARS',title:'The lights went out\none town at a time.',text:['First the schedules stopped. Then the fuel trucks. Then the voices on the other end of the line.','The grid broke into islands: a working panel on a roof, a battery behind a locked door, a camp keeping one lamp alive. Between them, the roads grew quiet.'],note:'Power remained. The connections did not.'},
 {label:'II / THE RUNNERS',title:'Someone still had\nto cross the distance.',text:['You carry what an electric bike can haul. Tools. A few cells. A scout small enough to see over the next ridge.','You ride between the places that still have something to give. Salvage becomes charge. Charge becomes distance. Every return trip is a promise you have to keep.'],note:'Ride. Scout. Scavenge. Keep going.'},
 {label:'III / 104.7 MHz',title:'Last night,\na voice came back.',text:['A broken message repeats from the northern tower. Too regular to be a dying battery. Too human to ignore.','Mara is waiting at the roadside camp. Your bike is ahead, a scout kit waits in her salvage box, and the battery reads twenty-seven percent. It is enough to begin.'],note:'“…if anyone can hear this… follow the line. We are still here.”'}
];
export function renderPrologue(page=0){const p=PROLOGUE[page]||PROLOGUE[0];return `<section class="prologue-page" aria-labelledby="prologueTitle"><div class="folio-kicker"><span>GRIDRUNNER / OPENING TRANSMISSION</span><span>${String(page+1).padStart(2,'0')} / 03</span></div><div class="prologue-copy"><span class="folio-label">${p.label}</span><h1 id="prologueTitle">${p.title.replace('\n','<br>')}</h1>${p.text.map(t=>`<p>${t}</p>`).join('')}<blockquote>${p.note}</blockquote></div><footer class="prologue-controls"><div class="story-pagination" aria-label="Opening story pages">${PROLOGUE.map((p,i)=>`<button data-story-page="${i}" aria-label="Story page ${i+1}" ${i===page?'aria-current="step"':''}>0${i+1}</button>`).join('')}</div><div><button data-story-action="skip">Skip intro</button><button class="primary" data-story-action="${page===2?'finish':'next'}">${page===2?'Follow the line':'Continue'} <span aria-hidden="true">→</span></button></div></footer></section>`;}

const key=(k,bindings)=>`<kbd>${esc((bindings[k]||k)===' '?'SPACE':(bindings[k]||k).toUpperCase())}</kbd>`;
export const MANUAL_SECTIONS=[['start','The first mile'],['ride','Bike & energy'],['scout','Scout operations'],['salvage','Pack & workshop'],['explore','Clues & exploration'],['controls','Controls & saves']];
function manualBody(id,b){const k=x=>key(x,b);switch(id){
 case 'ride':return {title:'Turn charge into distance.',deck:'A reserve is useful only if you can get home.',body:`<h3>Electric assist & human power</h3><p>${k('w')} accelerates. ${k('s')} brakes. Hold ${k('p')} while moving forward to pedal. At zero charge, forward movement uses your legs automatically. Slow down and rest to recover stamina. Heavy cargo costs energy.</p><h3>Keep the trailer working</h3><p>Stop near the trailer to manage its cargo and generator in <b>Equipment → Bike & trailer</b>. Select fuel or solar, then resume play. Generation fills the trailer; ${k('t')} transfers reserve charge to the bike. Solar needs daylight.</p><h3>Find a source</h3><p>${k('v')} locates remaining power. The stranded EV is a direct source. Repair a solar controller in the Workshop to use the solar yard. Substation charging requires a restored grid coupler and its rooftop relay.</p><aside class="folio-note">Fuel, stored energy and cargo capacity are finite. Check the return journey before committing to a long detour.</aside>`};
 case 'scout':return {title:'Look beyond the next bend.',deck:'Scout first. Bring the rider in second.',body:`<h3>Launch, fly, recover</h3><p>${k('q')} launches a docked drone and recalls an airborne one. ${k('w')}${k('a')}${k('s')}${k('d')} moves; mouse or arrow keys aim. ${k(' ')} climbs and ${k('shift')} descends. A recall is complete when the drone docks.</p><h3>Commands & cameras</h3><p>${k('1')} Follow · ${k('2')} Hold · ${k('3')} Dock · ${k('4')} FPV · ${k('5')} Scout ahead · ${k('6')} Orbit. ${k('h')} cycles camera views. Choose Stabilized or Acro in Settings. Touch / Xbox Mode 2: left stick lift/yaw; right stick forward/strafe (Stabilized) or pitch/roll (Acro). Centered lift gives hover thrust; a tilted Acro drone still loses height. Classic move/look remains available.</p><h3>Read the terrain</h3><p>${k('r')} scans nearby contacts. Tags remain in the map and journal after you return. ${k('k')} hides the scan overlay without erasing discoveries. ${k('n')} toggles night vision. Watch battery, signal and distance; obstacles can interrupt the link.</p><h3>Fleet & sensors</h3><p>Open FLEET to launch several unlocked aircraft and give each a separate command. Switching away from FPV leaves that drone holding position. Batteries, hull and returns are independent. Cyan beacons mark airborne drones; amber means returning home.</p><p>${k('b')} cycles visible, night vision, simulated thermal and RF. Thermal highlights people and active motors with normal wall occlusion. RF lists nearby carrier strength and compass bearing. ${k('l')} toggles the selected drone’s forward light. The HUD button switches Field, Navigation and Systems layouts.</p><h3>Autonomous survey</h3><p>After the opening tutorial, select an aircraft in Fleet and assign Survey ahead &amp; return. It flies to a fixed point, holds steady for five seconds, spends 3% charge to record nearby contacts, and physically docks at the bike. FPV or HOLD pauses the job; Resume continues it. Recall, another autonomous order or Cancel ends it. Safety returns never resume automatically. Jobs persist in saves but run only while play is resumed, not while menus or the app are closed. Flight Yard remains separate.</p><h3>Relay Outpost</h3><p>After onboarding, choose Fleet → Relay Outpost or press Shift+0. Relay finds a clear landing area about 240 m ahead. Scout waits for its link, then surveys about 460 m ahead and returns. Relay remains on the ground with rotors stopped and finite radio draw. Both aircraft need 40% battery, 30% hull and no existing job. Recall recovers Relay; terrain, weather, the bike-to-relay link and return reserve still limit reach.</p><h3>Mass & flight</h3><p>Scout and Relay are light, fast airframes. Utility and Cargo trade speed for equipment and payload. The Flight Yard recovery crate adds 6 kg: expect slower acceleration and climb, longer stops and higher battery use. Your backpack does not add drone mass. Lighter aircraft react more to wind.</p><h3>Specialist work</h3><p>Fit an engineer module in the Workshop and select the utility airframe in Fleet. At a perch receiver, keep the attached trailer within 240 m and use ${k('e')} to connect or disconnect. Watch the coupler heat.</p><button data-nav="flightyard">Practice in the Flight Yard</button>`};
 case 'salvage':return {title:'Nothing useful stays junk.',deck:'Recover materials. Build the tool. Open the next possibility.',body:`<h3>A pack you can read</h3><p>${k('i')} opens the Backpack. Search, filter by category, or sort by weight. Hover or focus a tile for a quick description; select it for equipment, salvage and cargo actions. On touch screens, tap to reach the item details.</p><h3>Recover & fabricate</h3><p>Use ${k('e')} at a container, then click items to take one or choose Take what fits. Leftovers persist in the box, including after saving. Broken appliances yield materials when you carry the right tool. A screwdriver and wrench are supplied. Make cutters, then assemble a pickaxe near your trailer. Mining takes four seconds; stay close.</p><p><b>Equipment → Workshop</b> lists fabrication and upgrades. Each recipe shows its material, tool, knowledge, power and station requirements. The Relay House workbench opens this same Workshop.</p><h3>Carry the right load</h3><p>The backpack holds 40 kg with the trailer attached, or 24 kg without it. Bike storage holds 12 kg and trailer cargo 60 kg. You must stand near a vehicle to transfer. Stored cargo still adds weight when you take that vehicle along.</p><aside class="folio-note">Keep unfamiliar relay components. Inspect their description and your evidence before deciding what to use.</aside>`};
 case 'explore':return {title:'Read what was left behind.',deck:'The route is also a record of the people who used it.',body:`<h3>Follow a clue</h3><p>Look for notes, radios, locked equipment and signs of recent work. Talk to the people at roadside stops. The Journal keeps evidence and discovered contacts; the Story archive records major events as you reach them.</p><h3>Work a site</h3><p>Walk close to an object and use ${k('e')}. Some spaces require the scout. Some repairs need an equipped item, a recipe learned from a clue, or a powered workbench. Inspect the situation before spending resources.</p><h3>Choose your approach</h3><p>Scout patrols and use cover or side routes. The bike, rider and drone can reach different places. If the screen feels crowded, hide scan labels with ${k('k')} and keep the map in the field menu.</p><aside class="folio-note">The manual explains your equipment. Puzzle combinations and later story outcomes are kept in discoveries, where you can find them for yourself.</aside><button data-nav="story">Open Story archive</button>`};
 case 'controls':return {title:'Keep your hands on the route.',deck:'These keyboard labels follow your current bindings. Weather and time randomize on each load; disable this in Light & weather for a fixed setup.',body:`<div class="manual-key-list">${[['Move / throttle','w'],['Interact','e'],['Mount / dismount','f'],['Launch / recall scout','q'],['Backpack','i'],['Map','m'],['Journal','j'],['Camera view','h'],['Find power','v'],['Transfer reserve','t'],['Hide scan labels','k'],['Night vision','n'],['Cycle sensors','b'],['Drone light','l']].map(([label,binding])=>`<div><span>${label}</span>${k(binding)}</div>`).join('')}</div><h3>Menu & controller</h3><p><kbd>TAB</kbd> opens the field menu; <kbd>ESC</kbd> pauses or returns. Use the Xbox D-pad to navigate menus, A to select and B to return. On foot or bike, use the left movement pad and drag to look. In drone Mode 2, use both sticks: left lift/yaw, right forward/strafe or Acro pitch/roll. Use HOLD to recover; select Classic in Settings for the previous layout.</p><button data-nav="controls">Full controls & remapping</button><h3>Protect your progress</h3><p><kbd>F5</kbd> saves manual slot 1. <b>Expedition → Save / load</b> provides three manual slots, autosave and JSON export/import. Export a backup before changing browsers or clearing browser data.</p><button data-nav="saves">Save / load</button>`};
 default:return {title:'Your first mile starts on foot.',deck:'A motorcycle, one scout, and a voice on the line.',body:`<ol class="manual-steps"><li><b>Find the motorcycle.</b><p>Walk forward and press ${k('f')} nearby to mount.</p></li><li><b>Salvage the first crate.</b><p>Ride northeast to the crate beside Mara’s camp. Press ${k('e')} to recover wire and cells.</p></li><li><b>Make a scout hop.</b><p>${k('q')} launches. Climb with ${k(' ')}, look around, then recall with ${k('q')}. Wait for docking.</p></li><li><b>Talk to Mara.</b><p>Approach her camp and press ${k('e')}. The wider route opens once you have finished the first salvage and flight.</p></li></ol><aside class="folio-note">The next step stays on screen during the opening tutorial. Controls, this manual and the Story archive remain available from the menu.</aside>`};
}}
export function renderManual(section='start',bindings={}){const id=MANUAL_SECTIONS.some(([x])=>x===section)?section:'start',p=manualBody(id,bindings),n=MANUAL_SECTIONS.findIndex(([x])=>x===id)+1;return `<div class="field-book"><header class="folio-heading"><span class="folio-label">BLACKLINE / RIDER’S HANDBOOK</span><h2>Field manual</h2><p>Carry knowledge. Travel lighter.</p></header><nav class="folio-tabs" aria-label="Manual sections">${MANUAL_SECTIONS.map(([x,label],i)=>`<button data-manual="${x}" ${x===id?'aria-current="page"':''}><span>0${i+1}</span>${label}</button>`).join('')}</nav><article class="folio-sheet" aria-labelledby="manualTitle"><div class="folio-kicker"><span>FIELD NOTES / 0${n}</span><span>SECTOR 07</span></div><h2 id="manualTitle">${p.title}</h2><p class="folio-deck">${p.deck}</p>${p.body}<div class="folio-signoff">KEEP THE LINE OPEN <span>0${n} / 06</span></div></article></div>`;}
export function renderStory(s){const entries=[
 ['00','Before the road',true,'The grid broke into islands of power. Runners linked them by carrying tools, cells and news between camps. You are one of them. Then a voice returned on 104.7 MHz.'],
 ['01','A voice in the basin',true,'A broken transmission repeats from the northern tower. Your route begins at Mara’s roadside camp with a bike, a scout and the charge you can recover along the way.'],
 ['02','Mara’s directions',s.met,'Mara shared parts and the route to the stranded EV, solar yard and substation. The old infrastructure still holds energy, if you can reach it and make it work.'],
 ['03','The relay answers',s.won||s.leg>1,'The first tower points to a source 147 km beyond the basin. The signal is not an ending. It is an invitation to keep going.'],
 ['04','Water & wire',s.leg>=2,'At the spillway, the route follows water and broken transmission lines. Cal and the waterworks stand between the rider and the next relay.'],
 ['05','The waterworks return',s.hydroRestored||s.leg>2,'The intake is clear and the breakers are aligned. Moving water has become usable power again. The northern relay can be reached.'],
 ['06','Black Start',s.leg>=3,'The industrial corridor leads to an awake facility. Its archive, security system and reserve tie the next transmission to the needs of the camps.'],
 ['07','The choice',s.leg3Won,s.ending==='restore'?'You directed the remaining power toward the camps. The line can carry a promise back home.':'You sent the transmission north. Somewhere beyond this region, the next part of the line may still be listening.']
 ];return `<div class="field-book story-book"><header class="folio-heading"><span class="folio-label">104.7 MHz / EXPEDITION RECORD</span><h2>The story so far</h2><p>A record of the line, revealed as you travel.</p><button data-story-action="replay">Replay opening story</button></header><div class="story-records">${entries.map(([number,title,seen,body])=>`<article class="story-record ${seen?'':'is-sealed'}"><span class="story-number">${number}</span><div><span class="folio-label">${seen?'RECORDED':'SIGNAL NOT YET RECEIVED'}</span><h3>${seen?title:'Beyond the known line'}</h3><p>${seen?body:'Continue the expedition to uncover this entry.'}</p></div></article>`).join('')}</div><div class="folio-signoff">YOUR JOURNEY IS STILL IN PROGRESS <button data-nav="guide">Read the field manual</button></div></div>`;}
